<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigDisabledUserEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigDisabledUserEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withDisabledUserEmail,
 * getDisabledUserEmail/disabledUserEmail accessors, and isDisabledUserEmailChanged with/without original.
 */
class TenantConfigDisabledUserEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDisabledUserEmail creates a new instance with the DisabledUserEmail set
     * from a string value, and getDisabledUserEmail returns the primitive string.
     */
    public function testWithDisabledUserEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDisabledUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withDisabledUserEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDisabledUserEmail());
    }
    /**
     * Asserts that withdisabledUserEmail has access to the value object
     * from a string value, and getDisabledUserEmail returns the primitive string.
     */
    public function testWithDisabledUserEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDisabledUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withDisabledUserEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->disabledUserEmail()->value());
    }
    public function testChangedDisabledUserEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigDisabledUserEmailAccessorUnitTest();
        $original = $holder->withDisabledUserEmail('one');
        $same = $holder->withDisabledUserEmail('one');
        $modified = $holder->withDisabledUserEmail('other');

        // Act
        $unchanged = $holder->isDisabledUserEmailChanged();
        $withSame = $original->isDisabledUserEmailChanged($same);
        $withDiferent = $original->isDisabledUserEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigDisabledUserEmailAccessorUnitTest
{
    use TenantConfigDisabledUserEmailAccessor;
}
